import {
  bilingualModules as baseModules,
  type BilingualLesson,
  type BilingualModule,
  type BilingualQuestion,
  type BilingualSection,
  type LocalText,
} from "./course-data-bilingual";

export type ReferenceItem = {
  title: string;
  kind: LocalText;
  url?: string;
  note: LocalText;
};

export type ExpandedModule = BilingualModule & {
  theoryIndex: number;
  objectives: LocalText[];
  caseStudy: {
    title: LocalText;
    setting: LocalText;
    evidence: LocalText[];
    task: LocalText;
  };
  activity: {
    title: LocalText;
    brief: LocalText;
    steps: LocalText[];
    deliverable: LocalText;
  };
  references: ReferenceItem[];
};

type LessonSpec = {
  base: [number, number];
  title: LocalText;
  lead: LocalText;
  heading: LocalText;
  paragraphs: LocalText[];
  bullets: LocalText[];
};

type ModuleSpec = {
  id: number;
  title: LocalText;
  shortTitle: LocalText;
  promise: LocalText;
  duration: string;
  image: string;
  imageAlt: LocalText;
  theoryIndex: number;
  objectives: LocalText[];
  lessons: LessonSpec[];
  caseStudy: ExpandedModule["caseStudy"];
  activity: ExpandedModule["activity"];
  lab: ExpandedModule["lab"];
  quiz: {
    scope: LocalText;
    evidence: LocalText;
    decision: LocalText;
    falseClaim: LocalText;
    monitor: LocalText;
  };
  references: ReferenceItem[];
};

const t = (en: string, es: string): LocalText => ({ en, es });
const ref = (
  title: string,
  kindEn: string,
  kindEs: string,
  noteEn: string,
  noteEs: string,
  url?: string,
): ReferenceItem => ({ title, kind: t(kindEn, kindEs), note: t(noteEn, noteEs), url });

