const adaptLesson = (spec: LessonSpec): BilingualLesson => {
  const original = baseModules[spec.base[0] - 1].lessons[spec.base[1]];
  const focus: BilingualSection = {
    heading: spec.heading,
    paragraphs: spec.paragraphs,
    bullets: spec.bullets,
  };
  return {
    ...original,
    title: spec.title,
    lead: spec.lead,
    duration: "35–45 min",
    sections: [...original.sections, focus],
  };
};

const buildQuestions = (s: ModuleSpec): BilingualQuestion[] => [
  {
    q: t(
      `Which starting point makes an analysis of “${s.shortTitle.en}” defensible?`,
      `¿Qué punto de partida hace defendible un análisis de «${s.shortTitle.es}»?`,
    ),
    options: [
      s.quiz.scope,
      t("Select the most favourable indicator first.", "Seleccionar primero el indicador más favorable."),
      t("Use the latest corporate headline as the baseline.", "Usar como línea base el último titular corporativo."),
      t("Assume civil-airline averages apply unchanged.", "Suponer que los promedios de aerolíneas civiles se aplican sin cambios."),
    ],
    answer: 0,
    feedback: t(
      `The correct starting point preserves scope and comparability: ${s.quiz.scope.en}`,
      `El punto de partida correcto preserva alcance y comparabilidad: ${s.quiz.scope.es}`,
    ),
  },
  {
    q: t("Which evidence package is strongest?", "¿Qué conjunto de evidencias es más sólido?"),
    options: [
      t("A supplier brochure and one successful trial.", "Un folleto del proveedor y un único ensayo satisfactorio."),
      t("A percentage improvement without a denominator.", "Una mejora porcentual sin denominador."),
      s.quiz.evidence,
      t("An expert opinion with no decision record.", "Una opinión experta sin registro de decisión."),
    ],
    answer: 2,
    feedback: t(
      `Evidence must connect the intervention to a controlled comparison: ${s.quiz.evidence.en}`,
      `La evidencia debe conectar la intervención con una comparación controlada: ${s.quiz.evidence.es}`,
    ),
  },
  {
    q: t("What is the best decision rule for the module case?", "¿Cuál es la mejor regla de decisión para el caso del módulo?"),
    options: [
      s.quiz.decision,
      t("Approve the option with the lowest single environmental score.", "Aprobar la opción con la menor puntuación ambiental única."),
      t("Delay until all uncertainty disappears.", "Aplazar hasta que desaparezca toda incertidumbre."),
      t("Use cost alone after legal compliance.", "Usar solo el coste tras comprobar el cumplimiento legal."),
    ],
    answer: 0,
    feedback: t(
      `A controlled decision uses explicit gates and conditions: ${s.quiz.decision.en}`,
      `Una decisión controlada utiliza condiciones y barreras explícitas: ${s.quiz.decision.es}`,
    ),
  },
  {
    q: t("Which statement must be rejected or rewritten?", "¿Qué afirmación debe rechazarse o reformularse?"),
    options: [
      t("The measured result applies to the stated site, period and boundary.", "El resultado medido se aplica al emplazamiento, periodo y alcance declarados."),
      s.quiz.falseClaim,
      t("The result excludes effects that were not measured.", "El resultado excluye los efectos que no se midieron."),
      t("A review is required if mission conditions change.", "Se requiere una revisión si cambian las condiciones de misión."),
    ],
    answer: 1,
    feedback: t(
      "An absolute or whole-system claim is not supported by a bounded result. State the baseline, metric, period, boundary, exclusions and uncertainty.",
      "Un resultado acotado no respalda una afirmación absoluta o de sistema completo. Hay que declarar línea base, métrica, periodo, alcance, exclusiones e incertidumbre.",
    ),
  },
  {
    q: t("Which control closes the learning loop?", "¿Qué control cierra el ciclo de aprendizaje?"),
    options: [
      t("Publishing the target.", "Publicar el objetivo."),
      t("Completing the first workshop.", "Completar el primer taller."),
      t("Archiving the model without an owner.", "Archivar el modelo sin responsable."),
      s.quiz.monitor,
    ],
    answer: 3,
    feedback: t(
      `Implementation is complete only when performance and triggers are owned: ${s.quiz.monitor.en}`,
      `La implantación solo se completa cuando hay responsables de desempeño y umbrales: ${s.quiz.monitor.es}`,
    ),
  },
];

const buildModule = (s: ModuleSpec): ExpandedModule => ({
  id: s.id,
  title: s.title,
  shortTitle: s.shortTitle,
  promise: s.promise,
  subtitle: s.promise,
  duration: s.duration,
  image: s.image,
  imageAlt: s.imageAlt,
  theoryIndex: s.theoryIndex,
  objectives: s.objectives,
  lessons: s.lessons.map(adaptLesson),
  caseStudy: s.caseStudy,
  activity: s.activity,
  lab: s.lab,
  questions: buildQuestions(s),
  references: s.references,
});

